{'content': '// Layout parameters
jar_od = 40;
tolerance = 1.0; // Total diameter clearance
hole_od = jar_od + tolerance;
wall_thickness = 2.4; // 2.4mm walls (multiple of 0.4mm nozzle)
cylinder_od = hole_od + 2 * wall_thickness;

grid_spacing = 45; // Overlap: cylinder_od is approx 45.8 -> 45 spacing ensures fusion

rows = 3;
cols = 3;

step_height = 30; // Height difference per row
base_floor_thickness = 3; 
cup_depth = 40; // Reduced slightly to ensure ease of removal but still secure
chamfer_height = 1.5;

$fn = 60;

module single_holder(r, c) {
    // Calculate heights
    // Row 0 is front. 
    floor_z = base_floor_thickness + r * step_height;
    top_z = floor_z + cup_depth;

    translate([c * grid_spacing, r * grid_spacing, 0]) {
        difference() {
            // Main Body
            union() {
                cylinder(h = top_z, d = cylinder_od);

                // Add fillets/connection material if needed? 
                // Because of overlap, natural fusion occurs.
                // We can add a chamfer at the bottom for nicer first layer?
                // No, flat is best for adhesion.
            }

            // The Hole
            translate([0, 0, floor_z]) {
                cylinder(h = cup_depth + 1, d = hole_od);
            }

            // To be safe, ensure the hole doesn't cut through the floor 
            // (Implicitly handled by starting at floor_z)

            // Top Chamfer for easy insertion
            translate([0, 0, top_z - chamfer_height]) {
                // Outer chamfer? No, inner chamfer.
                cylinder(h = chamfer_height + 0.1, d1 = hole_od, d2 = hole_od + 2*chamfer_height);
            }
        }
    }
}

// Generate the grid
union() {
    for (r = [0 : rows - 1]) {
        for (c = [0 : cols - 1]) {
            single_holder(r, c);
        }
    }

    // Optional: Add a common base plate if the overlap isn't enough?
    // With spacing 45 and OD = 40+1+4.8 = 45.8, overlap is 0.8mm.
    // This is adequate for FDM printing fusion.
    // However, to make it rigid, let's add small bridges or a hull between adjacent cylinders?
    // Doing a hull between (c, r) and (c+1, r) and (c, r+1) is cleaner.
}

// Reinforcements to ensure solid model
module bridges() {
    for (r = [0 : rows - 1]) {
        for (c = [0 : cols - 1]) {
            translate([c * grid_spacing, r * grid_spacing, 0]) {
                // Bridge to Right
                if (c < cols - 1) {
                    translate([grid_spacing/2, 0, 0])
                        linear_extrude(base_floor_thickness + r * step_height + cup_depth/2)
                            square([grid_spacing - cylinder_od + 4, 10], center=true);
                }
                // Bridge to Back
                if (r < rows - 1) {
                    translate([0, grid_spacing/2, 0])
                        linear_extrude(base_floor_thickness + r * step_height + cup_depth/2)
                            square([10, grid_spacing - cylinder_od + 4], center=true);
                }
            }
        }
    }
}
// Render bridges? 
// The cylinders interact with d=45.8 and spacing=45. The overlap is 0.8mm.
// This creates a continuous object but the "contact patch" is narrow.
// Let's add simple rectangular ribs between centers to stiffen it.
// Height of ribs: follow the height of the lower neighbor.

module stiffeners() {
    for (r = [0 : rows]) {
        for (c = [0 : cols]) {
             // Logic: Connect (r,c) to (r, c+1) and (r+1, c)

             // X-direction connections
             if (c < cols - 1 && r < rows) {
                 h = base_floor_thickness + r * step_height + cup_depth; // Height of current (lower or equal)
                 translate([c * grid_spacing, r * grid_spacing, 0])
                    hull() {
                        cylinder(h=h-5, d=5); // Inner point
                         translate([grid_spacing, 0, 0]) cylinder(h=h-5, d=5);
                    }
             }

             // Y-direction connections
             if (r < rows - 1 && c < cols) {
                 h = base_floor_thickness + r * step_height + cup_depth; // Height of current (lower)
                 translate([c * grid_spacing, r * grid_spacing, 0])
                    hull() {
                        cylinder(h=h-5, d=5);
                        translate([0, grid_spacing, 0]) cylinder(h=h+step_height-5, d=5); 
                        // Note: connecting to the taller back column, fill up to lower height
                        // Actually easier: just cube between them.
                    }
             }
        }
    }
}
// Actually, simple overlap is usually fine.
// Let's verify overlap in render.
