{'content': '// IKEA Citronhaj Spice Jar Stand
// Dimensions: Jar = 40mm diam, 120mm height.
// Grid: 3x3

jar_od = 40;
tolerance = 1.2; // Increase slightly for easier fit (41.2mm)
hole_od = jar_od + tolerance;
wall_thickness = 2.4; 
cylinder_od = hole_od + 2 * wall_thickness; // ~46.0mm

grid_spacing = 45.0; // Overlap: 46mm > 45mm, so 1mm overlap

rows = 3;
cols = 3;

step_height = 30; // Vertical step between rows
base_floor_thickness = 3; 
cup_depth = 40; // Depth of the holder cup
chamfer_height = 1.5;

$fn = 64;

module single_holder(r, c) {
    floor_z = base_floor_thickness + r * step_height;
    top_z = floor_z + cup_depth;

    translate([c * grid_spacing, r * grid_spacing, 0]) {
        difference() {
            // Positive shape
            cylinder(h = top_z, d = cylinder_od);

            // Cavity
            translate([0, 0, floor_z]) {
                cylinder(h = cup_depth + 1, d = hole_od);
            }

            // Beveled entry
            translate([0, 0, top_z - chamfer_height]) {
                 cylinder(h = chamfer_height + 0.1, d1 = hole_od, d2 = hole_od + 2*chamfer_height);
            }
        }
    }
}

module base_web() {
    // Creates a solid floor connecting all cylinders at the bottom
    // to improve bed adhesion and rigidity.
    h = base_floor_thickness;
    linear_extrude(height = h) {
        hull() {
            // Corners of the grid
            translate([0, 0]) circle(d=cylinder_od);
            translate([(cols-1)*grid_spacing, 0]) circle(d=cylinder_od);
            translate([0, (rows-1)*grid_spacing]) circle(d=cylinder_od);
            translate([(cols-1)*grid_spacing, (rows-1)*grid_spacing]) circle(d=cylinder_od);
        }
    }
}

// Alternatively, just hull adjacent ones to keep the "bubbly" shape
// rather than a big block which wastes material between curves.
module smart_base_web() {
    h = base_floor_thickness;
    union() {
        for (r = [0 : rows - 1]) {
            for (c = [0 : cols - 1]) {
                translate([c * grid_spacing, r * grid_spacing, 0]) {
                    // Connect to right
                    if (c < cols - 1) {
                        hull() {
                            cylinder(h=h, d=cylinder_od);
                            translate([grid_spacing, 0, 0]) cylinder(h=h, d=cylinder_od);
                        }
                    }
                    // Connect to back
                    if (r < rows - 1) {
                         hull() {
                            cylinder(h=h, d=cylinder_od);
                            translate([0, grid_spacing, 0]) cylinder(h=h, d=cylinder_od);
                        }
                    }
                     // Connect to diagonal (optional, fills the center hole)
                    if (c < cols - 1 && r < rows - 1) {
                         hull() {
                            cylinder(h=h, d=cylinder_od);
                            translate([grid_spacing, grid_spacing, 0]) cylinder(h=h, d=cylinder_od);
                        }
                    }
                }
            }
        }
    }
}

union() {
    // Generate Holders
    for (r = [0 : rows - 1]) {
        for (c = [0 : cols - 1]) {
            single_holder(r, c);
        }
    }

    // Generate Base Webbing
    smart_base_web();
}
'}

